using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.AI;
namespace DeliveryService.Mok.Editor {
public static class VenueStealthCheck {
 static string log;static void Check(bool ok,string text){log+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Logs/Venue-stealth-check.txt",log);if(!ok)throw new Exception(text);}
