 static void Place(VenueFinale m,Vector3 p){var t=new GameObject("test stand").transform;t.position=p;m.PlacePlayer(t);UnityEngine.Object.Destroy(t.gameObject);}
 public static IEnumerator Verify(){log="Venue stealth behaviour\n";yield return Wait(.5f);var m=VenueFinale.Current;var s=m.stealth;Check(Mathf.Approximately(s.detectionSeconds,3.5f),"faster 3.5 second suspicion saved");Check(!s.suspicionFill.sprite&&s.suspicionFill.type==UnityEngine.UI.Image.Type.Simple,"gauge uses plain geometry instead of stretched sprite");Check(!m.interior.transform.Find("Service corridor"),"obsolete service corridor and alley removed");Check(s&&s.guards.Length==3,"saved stealth and three patrol guards");var b=m.preparation.preparation.delivery.broker;var recon=m.preparation.preparation;
 typeof(BrokerMission).GetProperty("State").SetValue(b,BrokerMission.Phase.Complete);typeof(SpecialOrderMission).GetProperty("State").SetValue(recon.delivery,SpecialOrderMission.Phase.Complete);typeof(BackdoorMission).GetProperty("State").SetValue(recon,BackdoorMission.Phase.Complete);typeof(MechanicMission).GetProperty("State").SetValue(m.preparation,MechanicMission.Phase.Complete);b.day.EnterNightPreparation();StoryPhoneInbox.Current.AutoOpenEnabled=false;typeof(VenueFinale).GetProperty("EventDay").SetValue(m,b.day.currentDay);
 Check(m.Begin(),"mission begins");m.SkipCinematic();var move=m.Player.GetComponent<PlayerMove>();move.enabled=false;var look=m.Player.View.GetComponent<CameraMove>();look.enabled=false;m.PlacePlayer(m.entry);Check(m.Interact(),"admission accepted");m.SkipCinematic();look.enabled=false;
 yield return Wait(.3f);Check(s.guards.All(g=>g.gameObject.activeSelf),"patrols activate on admission");var g=s.guards[0];Vector3 start=g.transform.position;yield return Wait(3);Check(Vector3.Distance(start,g.transform.position)>.3f,"patrol walks between saved points");Check(g.GetComponentInChildren<Animator>().GetFloat("MoveSpeed")>.1f,"patrol animation receives speed");Check(g.GetComponentInChildren<Animator>().GetCurrentAnimatorClipInfo(0).Any(c=>c.clip.name=="Male_Walking"),"patrol plays actual walking clip");Check(s.Suspicion==0,"delivery reception is safe");BrokerMissionCheck.Capture(b,"Venue-stealth-entry");
 Place(m,m.deliveryTable.position+Vector3.back*2);Check(m.Interact()&&m.State==VenueFinale.Phase.Observe,"deposit starts infiltration");
 // 시야·벽·일시 정지·경고 후 회복을 실제 충돌체로 검사한다.
 s.enabled=false;foreach(var guard in s.guards){guard.enabled=false;var a=guard.GetComponent<NavMeshAgent>();if(a.isOnNavMesh)a.isStopped=true;}
 var w=m.interior.transform;g.GetComponent<NavMeshAgent>().Warp(w.TransformPoint(new Vector3(-18,.04f,3)));g.transform.rotation=Quaternion.LookRotation(Vector3.back);Place(m,w.TransformPoint(new Vector3(-18,.04f,0)));Physics.SyncTransforms();yield return null;Check(g.CanSee(m.Player),"patrol sees exposed player in front");float before=s.Suspicion;Time.timeScale=0;s.Tick(3);Check(s.Suspicion==before,"pause does not increase suspicion");Time.timeScale=1;s.Tick(2);Check(s.Warned&&s.Suspicion>before&&m.State==VenueFinale.Phase.Observe,"warning precedes discovery");BrokerMissionCheck.Capture(b,"Venue-stealth-warning");
 var cover=GameObject.CreatePrimitive(PrimitiveType.Cube);cover.transform.position=w.TransformPoint(new Vector3(-18,1.5f,1.5f));cover.transform.localScale=new Vector3(3,3,.3f);Physics.SyncTransforms();Check(!g.CanSee(m.Player),"solid cover blocks sight");s.Tick(7);Check(s.Suspicion==0&&!s.Seen,"hidden player loses suspicion");UnityEngine.Object.Destroy(cover);yield return null;
 foreach(var guard in s.guards)guard.gameObject.SetActive(false);
 foreach(var point in s.listeningPoints){m.PlacePlayer(point);look.enabled=false;m.Player.View.transform.LookAt(m.target.position+Vector3.up*1.4f);s.Tick(.1f);Check(m.CanObserve(),"clear listening sightline from "+point.name);}
 m.PlacePlayer(m.observeStand);look.enabled=false;m.Player.View.transform.LookAt(m.target.position+Vector3.up*1.4f);s.Tick(.1f);m.Observe(true,1);float progress=m.ObservationProgress;m.Observe(false,2);Check(progress>0&&m.ObservationProgress==progress,"listening progress survives release and cover");BrokerMissionCheck.Capture(b,"Venue-stealth-listening");
 // 정면 접근은 경고 후 기존 전투 단계로 이어진다.
 Place(m,m.target.position+m.target.forward*2);look.enabled=false;Physics.SyncTransforms();Check(s.TargetSeesPlayer(),"VIP notices direct close approach");s.Tick(1);Check(s.Suspicion>0&&m.State==VenueFinale.Phase.Observe,"VIP approach raises suspicion without instant failure");foreach(var guard in s.guards)guard.gameObject.SetActive(true);s.Tick(10);Check(m.State==VenueFinale.Phase.Exposed&&m.IntelSecured,"sustained exposure enters existing reveal and preserves essential intel");m.SkipCinematic();Check(m.State==VenueFinale.Phase.InteriorEscape&&m.Enemies.Length==3,"early discovery starts bounded escape combat");Check(m.Enemies.All(e=>e.GetComponentInChildren<Animator>().runtimeAnimatorController==g.chaseController),"discovery restores running controllers");Check(!s.guards.Any(x=>x.gameObject.activeSelf),"saved patrol templates remain hidden while live guards fight");m.Cancel();Check(!s.suspicionPanel.gameObject.activeSelf,"cancel hides suspicion UI");Check(m.Begin(),"retry remains possible");Check(s.Suspicion==0&&!s.Warned&&m.ObservationProgress==0,"retry resets suspicion and listening");
 m.SkipCinematic();m.PlacePlayer(m.entry);Check(m.Interact(),"retry admission works");m.SkipCinematic();s.enabled=true;
 Check(s.guards[0].Combat.ReceiveKick(m.Player,Vector3.forward,100),"patrol can be attacked through existing combat");yield return null;yield return null;Check(m.State==VenueFinale.Phase.Exposed&&!m.pizza.activeSelf,"attack before deposit triggers reveal without floating pizza");m.Cancel();move.enabled=true;look.enabled=true;
 }
}
